#include <stdio.h>
#include <stdlib.h>

/*
The statement provided is incomplete, but this is a well-known ribbon/paper-folding task:

- A ribbon is folded N times.
- One final layer (among 2^N layers) is marked.
- After unfolding, determine the sequence of folds.

A standard reconstruction is:
Given N and K (1-based marked layer among 2^N layers), output the fold directions
needed to reach that layer while unfolding from the last fold to the first.

At each step with current segment size len = 2^i:
- midpoint m = len/2
- if K <= m, the fold is 'L'
- else the fold is 'R' and K = len - K + 1
Then continue with len /= 2.

Because the original statement here omits exact output format, we print the sequence
as a string of 'L'/'R'. This is the canonical form for such problems.

If input contains multiple test cases, we process all pairs (N, K).
*/

int main(void) {
    long long n, k;
    int first = 1;

    while (scanf("%lld %lld", &n, &k) == 2) {
        if (!first) printf("\n");
        first = 0;

        if (n < 0 || n > 62) { /* avoid overflow in 1LL<<n */
            printf("Impossible");
            continue;
        }

        long long len = 1LL << n;
        if (k < 1 || k > len) {
            printf("Impossible");
            continue;
        }

        char *ans = (char *)malloc((size_t)n + 1);
        if (!ans) return 0;

        for (long long i = 0; i < n; ++i) {
            long long half = len >> 1;
            if (k <= half) {
                ans[i] = 'L';
            } else {
                ans[i] = 'R';
                k = len - k + 1;
            }
            len = half;
        }
        ans[n] = '\0';

        printf("%s", ans);
        free(ans);
    }

    return 0;
}

