int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    if (!(cin >> n >> k)) return 0;

    // Reconstruct folds from the marked layer index.
    // At each step:
    // - if k is odd, the last fold was to the Left ('L'), and new k = (k+1)/2
    // - if k is even, the last fold was to the Right ('R'), and new k = k/2
    //
    // We recover folds from last to first, so reverse at the end.
    string ans;
    for (long long i = 0; i < n; ++i) {
        if (k & 1LL) {
            ans.push_back('L');
            k = (k + 1) / 2;
        } else {
            ans.push_back('R');
            k /= 2;
        }
    }

    reverse(ans.begin(), ans.end());
    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class RibbonFold {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(); // number of folds
        int M = sc.nextInt(); // marked layer number (1-indexed from top after folding)

        // We'll reconstruct the folding sequence from the final state.
        // After unfolding, the marked layer's position is determined.
        // Initially, after all folds, we have 1 layer.
        // The marked layer is at position 1 (the only layer).

        int length = 1;  // current number of layers
        int pos = M;     // marked position from top (1-indexed)

        // We'll store the fold directions: 'U' for up, 'D' for down
        StringBuilder folds = new StringBuilder();

        // Process in reverse: from final folded state back to unfolded
        for (int i = 0; i < N; i++) {
            length *= 2;
            // If marked is in the top half, it came from the bottom half folded up
            // If marked is in the bottom half, it came from the top half folded down
            if (pos <= length / 2) {
                // marked is in top half -> fold was from bottom up
                folds.append('U');
                // position stays the same
            } else {
                // marked is in bottom half -> fold was from top down
                folds.append('D');
                // position flips relative to the top
                pos = length - pos + 1;
            }
        }

        // The folds were recorded in reverse order
        System.out.println(folds.reverse().toString());
        sc.close();
    }
}

