public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;

        long n = Long.parseLong(first);
        long k = fs.nextLong();

        StringBuilder ans = new StringBuilder();

        // We reconstruct folds from the last fold to the first.
        // At each step, for current segment length 2^n:
        // left half  -> fold was 'L'
        // right half -> fold was 'R', and index is mirrored.
        while (n > 0) {
            long half = 1L << (n - 1);
            if (k <= half) {
                ans.append('L');
            } else {
                ans.append('R');
                k = (1L << n) - k + 1;
            }
            n--;
        }

        System.out.println(ans.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

